pragma solidity >=0.8.0;
contract StoragePackingProbeReorderedUint16 {
    bool public b;
    uint8 public d;
    int32 public c;
    uint8 public a;
    uint16 public e;
    string public text;

    function setSmall(uint8 _a, bool _b, int32 _c, uint8 _d, uint16 _e) public {
        a = _a; b = _b; c = _c; d = _d; e = _e;
    }
    function setText(string memory t) public { text = t; }
    function clearA() public { delete a; }
    function length() public view returns (uint256) { return bytes(text).length; }
}
